        $e=[Content::class,'e'];$path=trim($path,'/');$token=$o['snapshot']??'';$href=static fn(string $p,array $q=[])=>$base.$p.(($q+($token?['snapshot'=>$token]:[]))?'?'.http_build_query($q+($token?['snapshot'=>$token]:[])):'');$asset=static fn(string $p)=>Content::asset('/themes/gallery/'.$p);
        $find=static function(array $rows,string $slug){foreach($rows as $p)if($p['slug']===$slug)return $p;return null;};$product=str_starts_with($path,'product/')?$find($products,substr($path,8)):null;$page=$find($pages,$path);
